from rcb_client import Robot
import numpy as np
from PIL import Image
r=Robot(); p=np.array(r.get_obs(cameras=['scene_cam'],video='none').meta['proprio']['now'][7:14]); q=p[3:].copy(); rows=[]
for a,b,n in [(p[:3],[p[0],p[1],.34],20),([p[0],p[1],.34],[0,.24,.34],30)]: rows.extend(np.linspace(np.r_[a,q],np.r_[b,q],n))
res=r.submit('ee_pose',rows,dt=.05,video='none',cameras=['practice_cam']);print('failures',sum(x['ik_failures'] for x in res.meta['plan']),'now',res.meta['proprio']['now'][7:10]);
o=r.get_obs(cameras=['practice_cam','scene_cam'],video='none');
for k,v in o.last.items():Image.fromarray(v).save('/app/output/clear_'+k+'.png')
print(r.status())
